import java.util.Scanner;
import java.math.BigInteger;

public class Main {
    static long factorial(int n) {
        BigInteger res = BigInteger.ONE;
        for (int i = 2; i <= n; i++) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        return res.longValue();
    }
    static long A(int n, int k) {
        return factorial(n) / factorial(n - k);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int mod = sc.nextInt();

        if (n == 1) {
            System.out.println(0);
            sc.close();
            return;
        }
        long[] z = {1};
        long aaa = 0;
        for (int i = 2; i <= n; i++) {
            int sizeN = i * i / 2;
            long[] nz = new long[sizeN];
            for (int j = 0; j < z.length; j++) {
                for (int k = 0; k < i; k++) {
                    if (z[j] > 0) {
                        nz[i - k - 1 + j] += z[j];
                    }
                }
            }
            long bbb = 0;
            long[] d = new long[z.length + 1];
            for (int w = z.length - 1; w >= 0; w--) {
                d[w] = (d[w + 1] + z[w]) % mod;
            }
            long[] e = new long[d.length + 1];
            long[] f = new long[d.length + 1];
            for (int w = 0; w < d.length; w++) {
                e[w + 1] = (e[w] + d[w]) % mod;
                f[w + 1] = ((f[w] - w * d[w]) % mod + mod) % mod;
            }
            for (int jj = 0; jj < z.length; jj++) {
                long ccc = 0;
                int L = jj + 2;
                int R = Math.min(z.length - 1, i + jj);
                if (R >= L) {
                    long deltaE = (e[R + 1] - e[L] + mod) % mod;
                    long deltaF = (f[R + 1] - f[L] + mod) % mod;
                    ccc = (ccc + (deltaE * (i + 1 + jj) + deltaF) % mod) % mod;
                }
                bbb = (bbb + ccc * z[jj]) % mod;
            }
            aaa += (bbb * A(n, n - i)) % mod;
            z = nz;
        }
        System.out.println(aaa % mod);
        sc.close();
    }
}

